typedef unsigned int nlUint32;
typedef unsigned int nslSoundId;
typedef unsigned int nslEmitterId;

enum nslSoundStatusEnum
{
  NSL_SOUNDSTATUS_INVALID = 0,
  NSL_SOUNDSTATUS_QUEUING,
  NSL_SOUNDSTATUS_READY,
  NSL_SOUNDSTATUS_PLAYING,
  NSL_SOUNDSTATUS_PAUSED
};

typedef enum
{
  NSL_CLEAR_INIT,
  NSL_CLEAR_RESET,
  NSL_CLEAR_FREE
} _nslClearBehaviour;

template<class T>
class fifo_queue
{
private:
  T *queue;
  short queue_max;
  short start;
  short end;
  short count;

public:
  T pop();
  int size() { return count; }
};

struct nslEmitter
{
  bool used;
  bool autoRelease;
  bool isALineEmitter;
  nslEmitterId myId;
  float startPosition[3];
  float endPosition[3];
  float position[3];
  fifo_queue<nslSoundId> emittedSounds;
};

struct nslSystem
{
  char beforeEmitters[0x1840];
  nslEmitter emitterSlots[256];
  char beforeEmitterCount[0x40];
  nlUint32 emitterSlotsUsedCount;
  int firstInit;
  int initialized;
  char beforeOn[0x2c];
  bool on;
};

extern nslSystem nsl;
extern void nslFatal(const char *, ...);
extern nslSoundStatusEnum nslGetSoundStatus(nslSoundId);
extern void nslStopSound(nslSoundId);
extern void _nslClearEmitterSlot(nlUint32, bool, _nslClearBehaviour);

inline void _nslInitialized()
{
  if (!(nsl.initialized == 1))
    nslFatal("NSL NOT INITIALIZED");
}

inline void _nslCheckEmitterIdValidity(nslEmitterId checkId)
{
  if (checkId == 0) return;
  nslEmitterId checkSlot = (checkId & 0x3ff);
  nslEmitterId upCheckId = checkId & 0xfffffc00;
  if (!(checkId != 0))
    nslFatal("Bad Emitter ID 0x%x\n", checkId);
  if (!(checkSlot < 256))
    nslFatal("Bad Emitter ID 0x%x\n", checkId);
  if (!(checkId == nsl.emitterSlots[checkSlot].myId))
    nslFatal("Bad Emitter ID 0x%x\n", checkId);
  if (!(upCheckId > 0))
    nslFatal("Bad Emitter ID 0x%x\n", checkId);
  if (checkSlot > 256)
    nslFatal("Bad Sound ID 0x%x SLOT NUMBER ABOVE SLOTS\n", checkId);
}

#define ASSERT_NSL_INITIALIZED() _nslInitialized()
#define ASSERT_EMITTER_ID_VALID(checkId) _nslCheckEmitterIdValidity(checkId)
#define NSL_GET_SLOT_FROM_ID(x) (x & 0x3ff)

void nslReleaseEmitter(nslEmitterId emitterToRelease)
{

  if (!nsl.on) return;
  ASSERT_NSL_INITIALIZED();
  ASSERT_EMITTER_ID_VALID(emitterToRelease);
  nsl.emitterSlotsUsedCount--;

  while (nsl.emitterSlots[NSL_GET_SLOT_FROM_ID(emitterToRelease)].emittedSounds.size())
  {
    nslSoundId mySound = nsl.emitterSlots[NSL_GET_SLOT_FROM_ID(emitterToRelease)].emittedSounds.pop();
    if ( nslGetSoundStatus( mySound ) != NSL_SOUNDSTATUS_INVALID )
      nslStopSound(mySound);  
  }

  _nslClearEmitterSlot(NSL_GET_SLOT_FROM_ID(emitterToRelease), false, NSL_CLEAR_RESET);
}
